const ozBiology11Zor = <(String, String, List<String>, String)>[
  ('Dilin arka kısmındaki bezlerden salgılanan dil lipazının bebeklerde ayrı bir önemi vardır. Bunun nedeni nedir?', 'Süt yağlarının sindirimine pankreas tam gelişmeden katkıda bulunması', ['Bebeklerin tükürüğünde amilaz hiç bulunmaması', 'Bebeklerde safranın yağları sindirmesi', 'Dil lipazının proteinleri de parçalaması'], 'Dil lipazı midede de bir süre etkinliğini koruyarak süt yağının bir kısmını parçalar; pankreas işlevi olgunlaşmamış bebeklerde bu katkı önemlidir.'),
  ('Yemek borusunun üst üçte birlik kısmının kas yapısı alt kısmından nasıl farklıdır?', 'Üst kısımda çizgili kas, alt kısımda düz kas bulunur.', ['Üst kısımda düz kas, alt kısımda kalp kası bulunur.', 'Tüm uzunluğu boyunca yalnız çizgili kas bulunur.', 'Üst kısımda kas yoktur, yalnız kıkırdak ve bağ dokusu bulunur.'], 'Yemek borusunun üst bölümü yutakla süreklilik gösterdiğinden çizgili kas içerir; alt bölüme doğru düz kas egemen olur.'),
  ('Kronik reflüde yemek borusunun alt ucundaki yassı epitelin mideye benzer silindirik epitele dönüşmesine ne ad verilir?', 'Barrett özofagusu', ['Akalazya', 'Pilor darlığı', 'Çölyak hastalığı'], 'Mide asidine uzun süre maruz kalan alt yemek borusunda epitel silindirik tipe dönüşür (metaplazi). Bu duruma Barrett özofagusu denir.'),
  ('Akalazya hastalığında yemek borusunun alt büzgen kası yutma sırasında gevşeyemez. Bu hastanın en belirgin şikâyeti hangisi olur?', 'Lokmanın göğüste takılması ve yutma güçlüğü', ['Mide asidinin sürekli ağza gelmesi', 'Yağlı dışkı çıkarılması', 'Kanda bilirubinin artması'], 'Alt büzgen kas açılmayınca besin yemek borusunda birikir; hasta lokmanın takıldığını hisseder ve yutma güçlüğü yaşar.'),
  ('Pariyetal hücreler mide boşluğuna H⁺ iyonu pompalarken kana eşdeğer miktarda bikarbonat verir. Yemekten sonra kan pH\'ının hafifçe yükselmesine verilen ad nedir?', 'Alkali dalga', ['Asit dalgası', 'Asidoz krizi', 'Tampon çöküşü'], 'Asit salgısı sırasında pariyetal hücrelerden kana bikarbonat geçer; yemek sonrası kan ve idrarda görülen bu hafif alkalileşmeye alkali dalga denir.'),
  ('Mide hücrelerinden salgılanan ve asit salgısını güçlü biçimde uyaran parakrin madde hangisidir? (Mide ülseri tedavisinde reseptörünü engelleyen ilaçlar kullanılır.)', 'Histamin', ['Sekretin', 'Somatostatin', 'Kolesistokinin'], 'Midedeki enterokromafin benzeri hücrelerden salgılanan histamin, pariyetal hücrelerdeki H2 reseptörlerine bağlanarak asit salgısını artırır; H2 bloke edici ilaçlar bu etkiyi engeller.'),
  ('Bebeklerin midesinde bulunan ve süt proteinini pıhtılaştırarak midede daha uzun kalmasını sağlayan enzim hangisidir?', 'Renin (kimozin)', ['Enterokinaz (bağırsaktaki etkinleştirici enzim)', 'Laktaz', 'Lipaz'], 'Kimozin (lab enzimi) sütteki kazeini pıhtılaştırır; böylece süt midede daha uzun kalır ve pepsinin etkisine daha fazla maruz kalır.'),
  ('Ameliyatla ileumunun son kısmı çıkarılan bir hastada uzun vadede hangi eksikliğin gelişmesi en olasıdır?', 'B12 vitamini eksikliği', ['C vitamini eksikliği ve diş eti kanaması', 'Glikoz eksikliği', 'Demir fazlalığı'], 'B12 vitamini iç faktöre bağlı olarak ileumun son kısmından emilir. Bu bölüm çıkarılınca B12 emilemez ve zamanla anemi gelişebilir.'),
  ('Disakkaritlerin sindiriminin bağırsak boşluğunda değil de epitel hücrelerinin zarında yapılmasının yararı nedir?', 'Oluşan monosakkaritlerin hemen yanındaki taşıyıcılarla emilebilmesi', ['Bakterilerin bu şekerleri daha kolay kullanması', 'Disakkaritlerin kana bozulmadan geçmesi', 'Enzimlerin mide asidiyle etkinleşmesi'], 'Fırçamsı kenar enzimleri ürünleri zar taşıyıcılarının hemen yakınında oluşturur; böylece monosakkaritler bağırsak bakterilerine kaptırılmadan hızla emilir.'),
  ('Tripsinin, kimotripsinojen ve prokarboksipeptidaz gibi diğer pankreas proenzimlerini de etkinleştirmesi sindirime nasıl bir katkı sağlar?', 'Az miktar etkin tripsinle birçok enzimin hızla ve zincirleme etkinleşmesine', ['Enzimlerin pankreas içinde etkinleşmesine', 'Proenzimlerin midede çalışmasına', 'Enzimlerin emilip kana geçmesine'], 'Enterokinazın başlattığı tripsin oluşumu, tripsinin diğer proenzimleri etkinleştirmesiyle çoğalır; böylece enzimler yalnız bağırsakta ve hızla devreye girer.'),
  ('Pankreas salgısını taşıyan kanal ile safra kanalı çoğu insanda nerede birleşerek onikiparmak bağırsağına açılır?', 'Vater kabarcığında', ['Pilor kapakçığında', 'Kör bağırsakta', 'Karaciğer kapısında'], 'Ana pankreas kanalı ve ortak safra kanalı Vater ampullasında birleşir; buradaki Oddi büzgen kası salgı akışını düzenler.'),
  ('Pankreas kanserinde pankreas başındaki bir tümörün sarılığa yol açabilmesinin nedeni nedir?', 'Ortak safra kanalını sıkıştırıp safra akışını engellemesi', ['İnsülin salgısını tamamen durdurması', 'Alyuvarları doğrudan parçalaması', 'Mide asidini artırması'], 'Safra kanalı pankreas başının içinden geçer. Bu bölgedeki tümör kanalı sıkıştırınca bilirubin bağırsağa geçemez ve kana birikerek sarılık yapar.'),
  ('Safra tuzlarının büyük kısmının ileumdan geri emilip kapı toplardamarıyla karaciğere dönmesi ve yeniden salgılanmasına ne ad verilir?', 'Enterohepatik dolaşım', ['Küçük dolaşım yoluyla akciğere geri gönderme', 'Lenf dolaşımı', 'Koroner dolaşım'], 'Safra tuzlarının yaklaşık %95\'i ileumdan emilip karaciğere döner; bu döngüye enterohepatik dolaşım denir.'),
  ('Sirozlu hastalarda yemek borusundaki toplardamarların genişleyip kanayabilmesi (özofagus varisi) en iyi nasıl açıklanır?', 'Kapı toplardamarındaki basınç artınca kanın yan yollara yönelmesi', ['Yemek borusundaki atardamarların daralması', 'Mide asidinin damar duvarını eritmesi', 'Kalbin pompalama gücünün aşırı artması'], 'Sertleşen karaciğer kapı toplardamarı kanına direnç gösterir; artan basınç (portal hipertansiyon) kanı yemek borusu çevresindeki toplardamarlara yönlendirir ve bunlar genişler.'),
  ('Glikoz ve galaktozun bağırsak hücresine alınmasında kullanılan taşıyıcıdan farklı olarak fruktoz hücreye hangi yolla girer?', 'Kolaylaştırılmış difüzyonla', ['Sodyumla birlikte aktif taşımayla', 'Fagositozla', 'Pinositozla'], 'Fruktoz, özel bir taşıyıcı proteinle derişim farkı yönünde kolaylaştırılmış difüzyonla emilir; ATP harcanmaz.'),
  ('Yağ asitleri ve monogliseritlerin bağırsak boşluğundan epitel hücrelerine ulaşmasını kolaylaştıran ve safra tuzlarıyla oluşan küçük kümelere ne ad verilir?', 'Misel', ['Şilomikron', 'Lipozom', 'Ribozom'], 'Safra tuzları yağ sindirim ürünlerini misel adı verilen küçük kümeler içinde taşır; miseller ürünleri mikrovillus yüzeyine iletir.'),
  ('Yağlı bir yemekten bir süre sonra alınan kan örneğinin plazmasının bulanık, süt gibi görünmesinin nedeni nedir?', 'Lenften kana geçen şilomikronların plazmada bulunması', ['Alyuvarların plazmada parçalanması', 'Plazma proteinlerinin çökmesi', 'Kanda glikozun kristalleşmesi'], 'Yağ emiliminden sonra şilomikronlar göğüs kanalı yoluyla kana geçer; bu büyük lipoprotein parçacıkları plazmayı bulanıklaştırır.'),
  ('Bağırsaktan emilen demirin vücuttaki miktarı genellikle nasıl düzenlenir?', 'Bağırsaktan emilen miktar ihtiyaca göre ayarlanarak', ['Fazlası idrarla hızla atılarak', 'Fazlası tükürükle salgılanarak', 'Fazlası akciğerden atılarak'], 'Vücudun demiri etkin biçimde atacak bir yolu yoktur; demir dengesi büyük ölçüde bağırsaktaki emilimin denetlenmesiyle sağlanır.'),
  ('Dışkılama (defekasyon) refleksinde iç anal sfinkter ile dış anal sfinkterin denetimi nasıl farklılaşır?', 'İç sfinkter istemsiz düz kasla, dış sfinkter istemli çizgili kasla çalışır', ['İkisi de istemli çizgili kasla çalışır', 'İkisi de istemsiz düz kasla çalışır ve bilinçli denetim yoktur', 'İç sfinkter istemli çizgili, dış sfinkter istemsiz düz kasla çalışır'], 'İç anal sfinkter düz kasla ve istemsiz, dış anal sfinkter çizgili kasla ve istemli denetlenir; bu yüzden dışkılama bir süre ertelenebilir.'),
  ('Ruminantlarda işkembedeki mikroorganizmalar öldükten sonra şirdene geçtiğinde hayvan için nasıl bir yarar sağlar?', 'Mikrop proteinleri sindirilerek hayvana amino asit kazandırır', ['Mikrobiyal selülozun glikoza dönüşmesini hızlandırır', 'Şirdendeki asidi tümüyle nötrler', 'Geviş getirmeyi tamamen ortadan kaldırır'], 'İşkembedeki bakteri ve protozoonlar şirdende sindirilir; böylece hayvan yüksek kaliteli mikrobiyal protein elde eder.'),
  ('Perikardın iki yaprağı arasında biriken fazla sıvı (perikardiyal efüzyon) kalp için hangi soruna yol açar?', 'Kalbin gevşeyip kanla dolmasını kısıtlayan bir baskı', ['Kalp kasının daha güçlü kasılmasına neden olan bir uyarı', 'Kapakçıkların tamamen sertleşmesine yol açan bir kireçlenme', 'Kalpteki kılcal damarların yeni oluşmasını sağlayan bir uyarı'], 'Sıvı kalbi dıştan sıkıştırır; karıncıklar diyastolde yeterince genişleyemez ve kalbe dönen kan ile atım hacmi azalır.'),
  ('Romatizmal ateş sonrasında mitral kapakçığın daralması (mitral stenoz) hâlinde hangi odacıkta basınç artışı beklenir?', 'Sol kulakçık', ['Sağ karıncık', 'Sol karıncık', 'Sağ kulakçık'], 'Dar kapakçıktan sol karıncığa kan geçmesi zorlaşır; sol kulakçıkta kan birikir ve basınç yükselir.'),
  ('Kalp döngüsünde karıncık sistolünün diyastolden kısa olmasının, kalp hızı artınca sorun yaratabilecek sonucu nedir?', 'Diyastol kısalır ve karıncıkların dolma süresi azalır', ['Sistol uzar ve atım hacmi büyür', 'Kapakçıklar sürekli açık kalır', 'Koroner akım diyastolde artar'], 'Hız arttıkça döngü kısalır ve kısalan kısım ağırlıklı diyastoldür; karıncıklar daha az dolar.'),
  ('Egzersizle kalp debisinin 5 L/dk\'dan 20 L/dk\'ya çıktığı bir kişide kalp hızı 70\'ten 140\'a çıkmıştır. Atım hacmi yaklaşık kaç mL\'den kaç mL\'ye geçmiştir?', '71\'den 143\'e', ['71\'den 71\'e', '143\'ten 71\'e', '50\'den 100\'e'], 'Dinlenmede 5000/70 yaklaşık 71 mL, egzersizde 20000/140 yaklaşık 143 mL olur; atım hacmi de artmıştır.'),
  ('Damarın yarıçapı iki katına çıkarsa, diğer koşullar sabitken Poiseuille yasasına göre akım yaklaşık kaç kat artar?', '16', ['2', '2 (yarıçapla doğru orantılı olarak)', '8'], 'Akım yarıçapın dördüncü kuvvetiyle orantılıdır; 2^4 = 16 kat artar.'),
  ('Beyni besleyen damar halkasının (Willis poligonu) önemi nedir?', 'Bir damar tıkandığında diğerlerinin beyne kan sağlamasına izin vermesi', ['Kanın yalnızca beyin dışına akmasını sağlaması', 'Beyindeki kanı doğrudan alt ana toplardamara taşıması', 'Beyne giden kanın oksijenini artırması'], 'Willis poligonu anastomozlar sayesinde yedek yol sağlar; böylece bir arterin tıkanması çoğu zaman beyin dokusunu tamamen kansız bırakmaz.'),
  ('Siroz gibi karaciğer hastalıklarında portal vendeki basınç artışının karın boşluğunda sıvı birikmesine (asit) yol açma mekanizması nedir?', 'Karaciğerden kan geçişi zorlaşır, kılcallardan sıvı sızar', ['Karaciğerde safra yapımı artar, sıvı karına dökülür', 'Portal ven genişleyip bağırsak emilimini artırır ve karnı doldurur', 'Hepatik arter daralır, böbrek sıvı tutar'], 'Portal venöz direnç artar; kılcallardaki basınç yükselir ve albümin düşüklüğüyle birlikte sıvı karın boşluğuna geçer.'),
  ('Hipofiz ön lobunu hipotalamusa bağlayan kapı dolaşımı için doğru ifade hangisidir?', 'İki ayrı kılcal ağ arasında özel bir toplardamar bulunur', ['Aorttan hipofize doğrudan kan taşıyan özel bir atardamar bulunur', 'Hipofiz ile karaciğer kapı toplardamarını paylaşır', 'İki kılcal ağ arasında kalp pompalar'], 'Portal sistem bir kılcal ağı başka bir kılcal ağa toplardamarla bağlar; hipotalamik hormonlar hipofize bu yolla taşınır.'),
  ('Doğumdan sonra bebeğin ilk soluğu ile akciğer kan damarlarındaki direncin düşmesi dolaşımı nasıl değiştirir?', 'Akciğere kan akışı artar ve foramen ovale kapanma yönünde basınç farkı oluşur', ['Kan göbek kordonundan gelmeye devam eder ve akciğer devre dışı kalır', 'Sağ kulakçık basıncı sol kulakçığı aşar ve kapak tamamen açılır', 'Arteriyal kanal genişleyip daha çok kan taşır'], 'Akciğer direnci düşünce sağ basınç azalır, sol kulakçık basıncı artar; basınç farkı foramen ovale kapağını kapatır.'),
  ('Yenidoğanda kalıcı olarak açık kalan arteriyal kanal (PDA) sonucunda hangi yönde kan akışı gerçekleşir?', 'Aorttan akciğer atardamarına', ['Akciğer atardamarından aorta', 'Sağ kulakçıktan sol kulakçığa', 'Portal venden hepatik vene'], 'Doğum sonrası sistemik basınç akciğerden yüksek olduğundan açık kanaldan kan aorttan pulmoner artere geçer.'),
  ('Kemik iliğinden kana yeni salınmış, çekirdeğini yeni atmış genç alyuvarlara ne ad verilir?', 'Retikülosit', ['Megakaryosit', 'Normoblast', 'Lenfoblast'], 'Retikülositler, çekirdeğini yeni atmış genç alyuvarlardır; kandaki oranları kemik iliği etkinliğinin göstergesidir.'),
  ('Kan sayımında alyuvar sayısı normal fakat hemoglobin düzeyi düşük bulunan kişide hangi tablo düşünülür?', 'Her alyuvarda hemoglobin içeriğinin azalması', ['Plazma hacminin tamamen azalması ve hematokritin yükselmesi', 'Akyuvar sayısının on kat artışı ve alyuvar çekirdeğinin korunması', 'Trombositlerin hemoglobin sentezlemesi'], 'Hemoglobin miktarı hücre başına düşmüşse (hipokromik tablo) demir eksikliği gibi nedenler akla gelir.'),
  ('Pıhtılaşma sürecinde Ca2+ iyonlarının gerekliliği hangi işlemde kendini gösterir?', 'Protrombinin trombine dönüşümünü sağlayan faktörlerin etkinleşmesinde', ['Fibrinin çözünmesinde ve plazminin yıkılmasında', 'Trombositlerin kemik iliğinden çıkmasında ve olgunlaşmasında', 'Alyuvarların hemoglobin yapımını başlatmasında'], 'Kalsiyum birçok pıhtılaşma faktörünün aktivasyonu için gereklidir; bu nedenle sitrat gibi kalsiyum bağlayanlar kanın pıhtılaşmasını önler.'),
  ('Heparin adlı maddenin tıpta pıhtılaşmayı önlemesi hangi etkisiyle ilgilidir?', 'Trombin etkisini baskılayan antitrombine bağlanması', ['Trombositleri çoğaltması', 'Fibrinojeni fibrine çevirmesi', 'K vitamini üretimini artırması'], 'Heparin antitrombinin etkisini güçlendirerek trombin ve diğer faktörleri baskılar.'),
  ('Kan basıncı ve kılcal sızıntı nedeniyle dokuya geçen sıvının büyük bölümü nereye döner?', 'Kılcal damarların toplardamar ucuna', ['Karaciğere portal ven yoluyla hızla', 'Böbreğe doğrudan süzülmek üzere', 'Hücrelerin içine ozmozla'], 'Sıvının büyük kısmı kılcalların venöz ucundan geri emilir; kalan kısım lenf damarları ile dolaşıma verilir.'),
  ('Ahtapot ve kalamar gibi kafadan bacaklıların dolaşım sistemi hangi özelliğiyle diğer yumuşakçalardan ayrılır?', 'Kapalı dolaşıma sahip olmasıyla', ['Hemolenf taşıması ile açık dolaşıma sahip olması', 'Kalpsiz olması', 'Yalnız difüzyonla beslenmesi'], 'Kafadan bacaklılar hızlı hareketleri için kapalı bir dolaşım ve birden çok kalp (iki solungaç kalbi, bir sistemik kalp) taşır.'),
  ('Timsahlarda diğer sürüngenlerden farklı olarak kalbin hangi özelliği vardır?', 'Karıncıkların tamamen ayrılmış olması', ['Tek kulakçık bulunması', 'Kalbin üç odacıklı kalması', 'İki kulakçığın birleşmesi'], 'Timsahların kalbi dört odacıklıdır; ancak sol ve sağ aort kemeri arasında bir bağlantı (Panizza deliği) vardır.'),
  ('Sağ ana bronşun sol ana bronşa göre daha geniş, kısa ve dik seyretmesinin klinik sonucu nedir?', 'Yutulan yabancı cisimlerin sağ akciğere kaçma olasılığının artması', ['Sağ akciğerin sol akciğerden daha küçük olması', 'Sol akciğere daha fazla kan gitmesi', 'Gırtlağın sağa doğru kayması'], 'Sağ bronş daha dik ve geniş olduğundan aspire edilen cisimler çoğunlukla bu tarafa gider.'),
  ('Pleural basıncın normalde atmosfer basıncının altında seyretmesinin akciğer için önemi nedir?', 'Akciğerlerin göğüs duvarına yapışık ve açık kalması', ['Akciğerlerin sürekli daralmasını ve göğüs duvarından ayrılmasını sağlaması', 'Alveollerin yağla dolmasını sağlaması', 'Diyaframın kalıcı olarak kasılmasını sağlaması'], 'Negatif pleural basınç, akciğerin elastik geri çekimine karşı onu göğüs duvarına doğru tutar.'),
  ('Sürfaktan eksikliğinde akciğerin esneme kapasitesindeki azalma nasıl açıklanır?', 'Yüzey gerilimi arttığı için alveollerin genişlemesi zorlaşır', ['Yüzey gerilimi azaldığı için alveoller sürekli açık kalır', 'Bronşların çapı genişler ve hava akımı hızlanıp alveoller kolayca açılır', 'Kılcallar ile alveol arasındaki mesafe artar'], 'Su filmi alveol iç yüzeyini çeker; sürfaktan yoksa bu gerilim yüksek kalır ve açılmak için fazla basınç gerekir.'),
  ('Aynı dakika havalanması (6000 mL/dk) olan iki kişiden A, 500 mL x 12 soluk; B ise 250 mL x 24 soluk alıyor. Ölü boşluk 150 mL ise hangisinin alveoler ventilasyonu daha yüksektir ve neden?', 'A; derin soluk alveole ulaşan oranı artırır', ['B; sık soluk alveole daha fazla taze hava taşır', 'İkisi eşit; dakika havalanması aynıdır', 'B; ölü boşluk kısa soluklarda daha etkilidir'], 'A için (500-150) x 12 = 4200 mL/dk, B için (250-150) x 24 = 2400 mL/dk; yüzeysel soluk verimsizdir.'),
  ('Spirometre ile artık hacim doğrudan ölçülemez. Bunun nedeni nedir?', 'Artık hava akciğerden dışarı verilemediği için spirometreye hiç girmez', ['Artık hacim çok küçük olduğundan cihaz bunu algılayamaz', 'Artık hava yalnızca kana geçtiği için cihaza uğramaz', 'Artık hacim soluk verme yedek hacmine eşit olduğundan ölçülmesi gereksizdir'], 'En kuvvetli soluk vermeden sonra bile akciğerlerde kalan hava dışarı verilemez; bu yüzden özel yöntemlerle hesaplanır.'),
  ('Amfizemli hastalarda artık hacmin artmasının nedeni nedir?', 'Alveol duvarlarının yıkılıp esnekliğin kaybolması nedeniyle havanın akciğerde tutulması', ['Bronşların genişleyip daha fazla hava çekmesi', 'Diyaframın kalınlaşıp sürekli kasılması', 'Alveol sayısının artıp hava geçişinin kolaylaşması'], 'Esneklik kaybı soluk vermeyi zorlaştırır; hava hapsolur, artık hacim yükselir.'),
  ('Venöz kandaki CO2 kısmi basıncı yaklaşık 46 mmHg, alveolde yaklaşık 40 mmHg\'dir. Bu durum için hangisi doğrudur?', 'CO2 kandan alveole geçer, fark küçük olsa da CO2 çok iyi çözündüğü için yeterlidir', ['CO2 alveolden kana geçer', 'CO2 geçişi gerçekleşmez', 'CO2 yalnız aktif taşımayla alveole geçer'], 'CO2\'nin çözünürlüğü O2\'ye göre yaklaşık 20 kat fazladır; küçük basınç farkı bile etkili difüzyon sağlar.'),
  ('Doku kılcalında alyuvardan çıkan HCO3- iyonlarına karşılık hücre içine giren iyon hangisidir ve bu olaya ne ad verilir?', 'Cl-; klorür kayması', ['Na+; sodyum kayması', 'K+; potasyum pompası', 'Ca2+; kalsiyum kayması'], 'HCO3- plazmaya çıkarken elektriksel dengeyi korumak için Cl- alyuvara girer; bu olaya klorür kayması denir.'),
  ('Haldane etkisi neyi ifade eder?', 'Oksijenlenmiş hemoglobinin CO2 bağlama kapasitesinin daha az olması', ['Oksijenlenmiş hemoglobinin CO2 bağlama kapasitesinin daha çok olması', 'Hemoglobinin CO2\'ye oksijenden daha ilgili olması', 'CO2 artınca doyum eğrisinin sola kayması'], 'Akciğerde hemoglobin oksijen bağlayınca CO2 ve H+ bırakır; bu CO2\'nin atılmasına katkıda bulunur.'),
  ('Hızlı ve derin soluyan (hiperventilasyon yapan) kişide kan pH\'ı nasıl değişir ve neden?', 'Yükselir, çünkü CO2 daha çok atılır', ['Düşer, çünkü daha çok oksijen alınır', 'Yükselir, çünkü bikarbonat azalır', 'Değişmez, çünkü tampon sistemi devreye girmez'], 'CO2 hızla atılınca karbonik asit azalır, kan alkalileşir (solunumsal alkaloz); baş dönmesi görülebilir.'),
  ('Merkezi kemoreseptörler hangi madde ile doğrudan uyarılır?', 'Beyin omurilik sıvısındaki H+ iyonları', ['Alyuvardaki hemoglobin', 'Plazmadaki albümin', 'Alveoldeki sürfaktan'], 'CO2 beyin omurilik sıvısına geçince H+ artışı yapar; bu H+ merkezi kemoreseptörleri uyarır.'),
  ('Derin ve uzun süre hiperventilasyon yaptıktan sonra nefesini normalden daha uzun tutabilen kişide bunun nedeni nedir?', 'Kanda CO2\'nin azalıp solunum uyaranının gecikmesi', ['Kandaki O2\'nin kalıcı olarak artması ve CO2\'nin düşmesi', 'Kandaki CO2\'nin fazla birikmesi', 'Solunum merkezinin çalışmaya devam etmemesi'], 'CO2 düşük olduğundan soluk alma isteği geç doğar; oysa oksijen azalmış olabilir ve bilinç kaybı riski artar.'),
  ('Uykuda solunumun duraklamalarıyla karakterize uyku apnesi hâlinde sabah baş ağrısı görülmesinin nedeni aşağıdakilerden hangisidir?', 'Gece boyunca kanda CO2 birikmesi ve oksijen azalması', ['Gece boyunca kandaki glukozun yükselmesi', 'Beyindeki dopaminin artması', 'Karaciğerdeki glikojenin azalması'], 'Duraklama sırasında CO2 yükselir, O2 düşer; beyin damarları genişleyerek baş ağrısı yapabilir.'),
  ('Yüksek rakımda ilk günlerde idrar miktarının artması ve kanın bazikleşmesi nasıl açıklanır?', 'Hızlı soluma ile CO2 atılması ve böbreğin bikarbonat atarak dengeyi sağlaması', ['Alyuvarların patlaması ve idrara hemoglobin geçmesi', 'Karaciğerin aşırı üre üretmesi ve böbreğin asit atması', 'Sindirimin hızlanıp sıvı kaybının artması'], 'Hiperventilasyon CO2\'yi düşürür, kan pH\'ı yükselir; böbrek bikarbonat atarak dengeyi onarmaya çalışır.'),
  ('Serbest dalış yapan dalgıçlar dalıştan önce hiperventilasyon yapmaktan neden sakınmalıdır?', 'CO2 düşüp soluk alma isteği gecikir, oksijen bitince bilinç kaybı olabilir', ['CO2 yükselip kandaki oksijeni hızla tüketir ve bilinç kaybettirir', 'Oksijen zehirlenmesiyle akciğer dokusu hasar görür', 'Kan pH\'ı düşüp kalp hızı kontrolsüz yükselir'], 'CO2 düzeyi yapay olarak düşük olduğundan solunum uyaranı geç gelir; bu sırada oksijen tehlikeli seviyeye inebilir.'),
  ('Derin dalışta azot narkozu (derin sarhoşluğu) yaşanmasının nedeni nedir?', 'Yüksek basınçta çözünen azotun sinir hücreleri üzerindeki uyuşturucu etkisi', ['Dokularda karbondioksit kabarcıkları oluşması', 'Hemoglobinin azotu oksijen sanarak bağlaması', 'Beyindeki oksijenin tamamen tükenmesi'], 'Yüksek kısmi basınçta çözünen azot, sinir iletimini etkileyerek yargı ve koordinasyonu bozar.'),
  ('Dalgıcın uzun bir şnorkelle (örneğin 1 metre) soluk almaya çalışması neden verimsizdir?', 'Ölü boşluk hacmi artar ve taze hava miktarı azalır', ['Atmosfer basıncı artar ve oksijen yüzdesi azalır', 'Akciğerlerin hacmi küçülür ve alveol sayısı düşer', 'Hava yolunda sürfaktan birikir ve difüzyonu tamamen keser'], 'Şnorkeldeki hava ölü boşluğa katılır; her soluk alışta alveollere ulaşan taze hava azalır.'),
  ('Spirometrede FEV1/FVC oranının normalin altında çıkması hangi hastalık grubunu düşündürür?', 'Tıkayıcı (obstrüktif) akciğer hastalıkları', ['Kısıtlayıcı akciğer fibrozu ve kemik hastalıkları', 'Kalp kapakçık hastalıkları', 'Karaciğer hastalıkları'], 'Obstrüktif hastalıklarda ilk saniyede verilen hava oranı düşer; astım ve KOAH örnektir.'),
  ('Tüberküloz (verem) basili akciğerde hangi hücrelerin içinde yaşayabilir?', 'Alveol makrofajları', ['Alveol tip II hücreleri', 'Silli epitel hücreleri', 'Alyuvarlar'], 'Mycobacterium tuberculosis, makrofajlar tarafından yutulur ama hücre içinde canlı kalabilir.'),
  ('Alyuvarsız bir sıvıyla beslenen laboratuvar fareleri solunum için neden gene de oksijen gazına gereksinim duyar?', 'Hücre solunumunda oksijen, elektron taşıma sisteminin son alıcısıdır', ['Oksijen DNA yapımı için doğrudan hammaddedir', 'Oksijen suyu karbondioksite çevirir', 'Hücre zarındaki kanalları açmak için gereklidir'], 'Oksijensiz elektron taşıma durur, ATP üretimi azalır; hücre ölümü başlar.'),
  ('Balık solungaçlarında su akışı ve kan akışının zıt yönlü olması (karşıt akım) neyi sağlar?', 'Su boyunca bütün noktalarda oksijen difüzyon gradyanının korunması', ['Kanın solungaçtan geçiş süresinin kısalması', 'Suyun solungaçta durması ve oksijenin birikmesi', 'Alyuvarların solungaçta yıkılması'], 'Karşıt akımda kan, her noktada kendinden daha oksijenli suyla karşılaşır; oksijenin %80\'inden fazlası alınır.'),
  ('Karaciğerdeki Kupffer hücrelerinin görevi aşağıdakilerden hangisidir?', 'Kandaki yaşlı hücreleri ve bakterileri fagositozla temizlemek', ['Safra tuzlarını üretmek', 'Glikojen depolamak', 'Albümin sentezlemek'], 'Kupffer hücreleri karaciğer sinüzoidlerindeki özel makrofajlardır.'),
  ('Pankreas lipazı yağ sindirimini tamamlarken ürünlerini nasıl oluşturur?', 'Trigliseriti bir monogliserit ve iki yağ asidine ayırarak', ['Trigliseriti üç gliserole ve bir yağ asidine ayırarak', 'Trigliseriti glukoza ve amino asitlere dönüştürerek', 'Trigliserit yapısını bozmadan emülsiyona sokarak'], 'Lipaz, trigliseridin 1. ve 3. esteri bağlarını keser; ana ürünler 2-monogliserit ve serbest yağ asitleridir.'),
  ('Kistik fibrozlu hastaların pankreas kanallarının koyu mukusla tıkanması hangi sonucu doğurur?', 'Enzimlerin bağırsağa ulaşamaması ve yağ ile proteinlerin sindirilememesi', ['Karaciğerde safra yapımının durması ve sarılık', 'Mide asidinin artıp ülser oluşması', 'Kan şekerinin düşmesi'], 'Tıkalı kanallar pankreas salgısını bağırsağa geçirmez; besinler tam sindirilemez ve yağlı dışkı oluşur.'),
  ('İnce bağırsakta fruktozun emilmesi için hangi mekanizma kullanılır?', 'Taşıyıcı proteinle kolaylaştırılmış difüzyon', ['Na+ ile birlikte aktif taşıma', 'Na+ ile birlikte aktif taşıma ve ATP harcanması', 'Pinositoz'], 'Fruktoz, GLUT5 taşıyıcısı ile enerjisiz biçimde derişim farkı yönünde emilir.'),
  ('Bağırsak hücresinde sentezlenen şilomikronlar kana neden doğrudan geçemez?', 'Çok büyük olduğundan kan kılcal porlarından sığmazlar, lenf kılcalına geçerler', ['Hücre içinde parçalandıkları için kana ulaşamazlar', 'Albüminle bağlandıklarından kılcalda kalırlar', 'Alyuvar zarına bağlanıp hücre içinde birikirler'], 'Şilomikronlar apolar yağları taşıyan büyük lipoprotein kümeleridir; lakteallere girer ve lenfle dolaşıma karışır.'),
  ('Adrenalinin kalp üzerindeki etkisi hangi reseptörler yoluyla gerçekleşir?', 'Beta-1 adrenerjik reseptörler', ['Muskarinik asetilkolin reseptörleri', 'Nikotinik reseptörler', 'İnsülin reseptörleri'], 'Kalp kasındaki beta-1 reseptörleri adrenalin ve noradrenaline yanıt verip hız ve kuvveti artırır.'),
  ('Koroner arterlerin büyük bölümü kalp kasını kalp döngüsünün hangi evresinde besler?', 'Diyastolde', ['Sistolde ve diyastolde aynı oranda', 'Yalnız izovolümetrik kasılmada', 'Yalnız kulakçık sistolünde'], 'Sistolde kasılan miyokard damarları sıkıştırdığından en çok akım diyastolde olur.'),
  ('Anjiyotensin II hangi etkiyle kan basıncını artırır?', 'Arteriyolleri daraltması ve aldosteron salgısını artırması', ['Kalbi yavaşlatması ve damar çapını genişletmesi', 'Trombosit sayısını artırması', 'Safra yapımını artırması'], 'Anjiyotensin II güçlü bir damar daraltıcıdır; ayrıca böbreküstü bezini uyararak Na+ tutulmasını sağlar.'),
  ('Atriyal natriüretik peptit (ANP) kalpten salgılandığında kan basıncına etkisi nedir?', 'Böbreklerden Na+ ve su atılımını artırarak basıncı düşürür', ['Aldosteron salgısını artırarak basıncı yükseltir', 'Damarları daraltarak basıncı yükseltir', 'Kan hacmini artırarak basıncı yükseltir'], 'Kulakçıklar gerilince ANP salınır; böbrekten tuz ve su atılımı artar, kan hacmi ve basıncı düşer.'),
  ('Bir kişinin midesinin büyük kısmı bariyatrik ameliyatla küçültülüyor. Uzun vadede B12 eksikliği riski neden artar?', 'İç faktörü salgılayan pariyetal hücrelerin sayısı azalır', ['Safra tuzu salgısı durur', 'Pankreastaki zimojenler etkinleşmez', 'Kalın bağırsak bakterileri B12\'yi sentezleyemez'], 'İç faktör olmadan B12 ileumdan emilemez; mide dokusunun azalması iç faktör yapımını düşürür.'),
  ('Bir hastada mide asidi sürekli çok yüksektir ve onikiparmak bağırsağında ülser görülmektedir. Bunun olası nedeni aşağıdakilerden hangisi olabilir?', 'Gastrin salgılayan bir tümör nedeniyle aşırı asit üretilmesi', ['Kolesistokinin eksikliğine bağlı safra yetersizliği', 'Pankreas lipazının fazla salgılanması', 'İç faktör eksikliği ve B12 azlığı'], 'Aşırı gastrin (Zollinger-Ellison) pariyetal hücreleri sürekli uyarır; fazla asit duodenum mukozasını yaralar.'),
  ('Midedeki mukus tabakasının kalınlığının azalmasına yol açan aspirin gibi ilaçlar neden mide ülseri riskini artırır?', 'Prostaglandin sentezini azaltarak mukus ve bikarbonat salgısını düşürürler', ['Gastrin salgısını durdurup asidi artırırlar', 'Pepsinojeni doğrudan pepsine çevirirler', 'Safra tuzlarını mideye geri akıtırlar'], 'Prostaglandinler mide koruyucu mukus ve bikarbonatı artırır; aspirin bunu engeller.'),
  ('Mide asidi alkali bir antasit alınınca nötrleştiğinde gastrin salgısı nasıl etkilenir?', 'Artar, çünkü pH yükselince negatif geri bildirim azalır', ['Azalır, çünkü pH yükselince gastrin etkisiz hâle gelir ve G hücreleri susar', 'Değişmez, çünkü gastrin yalnızca sinirle denetlenir', 'Sıfırlanır, çünkü G hücreleri ölür'], 'Asit gastrini baskılar; antasitle pH yükselince baskı kalkar ve gastrin artar (asit sıçraması).'),
  ('Doğuştan ventriküler septal defekt (VSD) olan bir bebekte sol karıncıktan sağ karıncığa kan geçişi hangi sonucu doğurur?', 'Akciğere giden kan miktarı artar', ['Aorta giden kan miktarı artar', 'Akciğere giden kan miktarı sıfırlanır', 'Sağ kulakçığa kan akışı durur'], 'Sol karıncık basıncı daha yüksek olduğundan kan sağa kaçar; akciğer dolaşımı aşırı yüklenir.'),
  ('Fallot tetralojisi gibi kalp anomalilerinde bebeğin mor görünmesinin (siyanoz) nedeni nedir?', 'Oksijensiz kanın sistemik dolaşıma karışması', ['Akyuvarların fazla üretilmesi', 'Hemoglobinin altın renkli olması', 'Safra pigmentinin deriye çökmesi'], 'Anormal bağlantılarla oksijensiz kan sol tarafa geçer; arteriyel kanda oksijen düşer, deri morarır.'),
  ('Arteriyel kanda 20 mL/100 mL, venöz kanda 15 mL/100 mL oksijen bulunuyor. Kalp debisi 5 L/dk ise dokuların dakikada tükettiği oksijen kaç mL\'dir?', '250', ['100', '500', '750'], 'Arteriyovenöz fark 5 mL/100 mL; 5000 mL/dk kan x 0,05 = 250 mL/dk oksijen tüketimi.'),
  ('Karbonmonoksit zehirlenmesinde hastanın cildinin kiraz kırmızısı görünmesine neden olan bileşik hangisidir?', 'Karboksihemoglobin', ['Methemoglobin', 'Oksihemoglobin', 'Karbaminohemoglobin'], 'CO hemoglobine oksijenden yaklaşık 200 kat güçlü bağlanarak parlak kırmızı karboksihemoglobin oluşturur.'),
  ('Siyanür zehirlenmesinde dokular kanda yeterli oksijen olmasına rağmen oksijen kullanamaz. Bu durum neden olur?', 'Mitokondrideki sitokrom oksidaz enziminin engellenmesi', ['Hemoglobinin oksijenden ayrılması', 'Alveollerin hava ile dolması', 'Plazma proteinlerinin parçalanması'], 'Siyanür elektron taşıma sisteminin son enzimini durdurarak hücresel solunumu bloke eder.'),
  ('Fetüs akciğerlerinin sıvıyla dolu olmasına rağmen doğumdan sonra hava ile dolabilmesi nasıl sağlanır?', 'Sıvının doğum sürecinde ve ilk soluklarda emilip lenf ve kana geçmesi', ['Sıvının solunum sırasında buharlaşması', 'Sıvının göbek kordonundan geri dönmesi', 'Sıvının sindirilip mideye geçmesi'], 'Doğum stresi ve ilk soluklar sıvının dışarı atılmasını ve emilmesini sağlar.'),
  ('Sempatik sinir sisteminin tükürük salgısına etkisi hangisidir?', 'Az ve koyu tükürük salgılanması', ['Çok ve sulu tükürük salgılanması', 'Salgının tamamen durması ve kuru ağız', 'Değişim olmaz'], 'Parasempatik bol ve sulu tükürük verir; sempatik uyarı az ve koyu mukuslu tükürüğe yol açar.'),
  ('Ortalama arter basıncı 100 mmHg, sağ kulakçık basıncı 0 mmHg, kalp debisi 5 L/dk ise toplam periferik direnç kaç mmHg·dk/L\'dir?', '20', ['500', '0,05', '5'], 'Direnç = basınç farkı / debi = 100 / 5 = 20.'),
  ('Aortun kesit alanı yaklaşık 3 cm², tüm kılcal ağın kesit alanı yaklaşık 3000 cm²\'dir. Aortta akış hızı 30 cm/s ise kılcal ağda yaklaşık kaç cm/s olur?', '0,03', ['0,3', '0,3 (hız on kat daha yüksek)', '30'], 'Süreklilik: A1 v1 = A2 v2; 3 x 30 = 3000 x v2; v2 = 0,03 cm/s.'),
  ('Bir yaşlı kişide sistolik basıncın yükselip diyastolik basıncın düşmesiyle nabız basıncının artması neyin göstergesi olabilir?', 'Aort ve büyük atardamarların esnekliğini yitirmesinin', ['Kalp kapakçıklarının yeni oluşmasının', 'Kılcal damarların çoğalmasının', 'Alyuvar sayısının düşmesinin'], 'Sertleşen büyük arterler sistolde gerilemez, diyastolde basıncı sürdüremez; nabız basıncı genişler.'),
  ('Ruminantlarda işkembedeki mikroorganizmaların selülozu parçaladıktan sonra oluşan başlıca ürünler hangileridir?', 'Uçucu yağ asitleri', ['Aminoasitler', 'Glikoz ve amino asitler', 'Laktik asit'], 'Mikroplar selülozu fermente ederek uçucu yağ asitleri (asetat, propiyonat, bütirat) üretir; bunlar hayvanın başlıca enerji kaynağıdır.'),
  ('At, tavşan ve fil gibi geviş getirmeyen otçullarda selülozun fermantasyonu hangi organda yapılır?', 'Büyük kör bağırsak ve kolon', ['Mide ve onikiparmak bağırsağı', 'Karaciğer ve safra kesesi', 'Yemek borusu ve kursak'], 'Bu hayvanlarda fermantasyon sindirim kanalının arka kısmında olur; bu bölümde emilim daha verimsizdir.'),
  ('Koala gibi bazı otçul keseli hayvanlar yalnız okaliptüs yaprağı yer. Bunun için yapısal bir uyum hangisidir?', 'Çok uzun bir kör bağırsak', ['Kısa ve geniş bir ince bağırsak', 'Güçlü bir kursak', 'Dört odacıklı bir mide'], 'Uzun kör bağırsak yaprak liflerinin ve zehirli bileşiklerin mikroplarla parçalanması için zaman verir.'),
  ('Alveol havalanması (ventilasyon) iyi, fakat kılcal kan akımı (perfüzyon) yetersiz olan bir akciğer bölgesinde ne olur?', 'Gaz alışverişi gerçekleşmez, bu bölge ölü boşluk gibi davranır', ['Oksijen kısmi basıncı düşer ve CO2 birikir', 'Kan oksijenle fazla yüklenir', 'Alveol çöker ve sürfaktan artar'], 'Kan olmadığında alışveriş yapılmaz; havalanan ama kanlanmayan alanlar fizyolojik ölü boşluk sayılır.'),
  ('Akciğerde oksijeni düşük alveollerin çevresindeki damarların daralması (hipoksik vazokonstriksiyon) ne sağlar?', 'Kanı iyi havalanan alveollere yönlendirmek', ['Kanı kötü havalanan alveollere yönlendirmek', 'Kan basıncını sıfıra indirmek', 'Alveolleri tamamen kapatmak'], 'Kötü havalanan bölgeye kan akışı azaltılır; böylece perfüzyon ile ventilasyon eşleşir.'),
  ('Akciğerlerin tepe ve taban bölgeleri karşılaştırıldığında ayakta duran bir insanda kan akımı nasıl dağılır?', 'Taban bölgelerinde daha fazla', ['Tepe bölgelerinde daha fazla, çünkü orada basınç düşüktür', 'İki yerde de aynı', 'Yalnız orta bölgelerde'], 'Yerçekimi nedeniyle akciğer tabanındaki damarların basıncı yüksektir; alt bölgeler daha çok kanlanır.'),
  ('Böcek trakeolleri ucunda sıvı bulunmasının işlevi nedir?', 'Gazların hücre yüzeyine difüzyonunu kolaylaştırmak', ['Hemolenfin oksijen taşımasını sağlayıp kana karıştırmak', 'Oksijenin ekzoskeletten geçmesini engellemek', 'Hücrelerdeki karbondioksiti depolamak'], 'Trakeolün ucundaki sıvı, gaz alışverişinin hücre zarı yakınında difüzyonla gerçekleşmesini sağlar; trake sisteminin uçları bir gaz alışveriş yüzeyidir.'),
  ('Büyük böceklerin sırt-karın yönünde abdomen kasları ile yaptıkları ventilasyon hareketlerinin amacı nedir?', 'Trakelerdeki havayı değiştirmek', ['Hemolenfi akciğere itmek ve basıncını artırmak', 'Kitin zırhı kalınlaştırmak', 'Besinleri öğütmek'], 'Ventilasyon hareketleri hava keselerini sıkıp genişleterek trake içinde hava akımı oluşturur.'),
  ('Aplastik anemide kemik iliğinde ne olur?', 'Kök hücreler azalır ve bütün kan hücrelerinin üretimi düşer', ['Yalnız alyuvarlar bölünür ve miktar artar', 'Akyuvarlar tek başına artar', 'Trombositler kemik iliğinden çıkamaz'], 'Aplastik anemide ilik üretimi yetersizdir; alyuvar, akyuvar ve trombosit birlikte azalır.'),
  ('Hemolitik anemide hastanın ciltte sararma ve idrar renginde koyulaşma yaşamasının nedeni nedir?', 'Alyuvarların aşırı yıkımıyla bilirubinin artması', ['Karaciğerde safra yapımının durması', 'Kemik iliğinde hemoglobin yapımının aşırı artması', 'Plazma proteinlerinin idrara geçmesi'], 'Alyuvarlar hızla yıkılınca bilirubin yükselir; sarılık ve koyu idrar görülür.'),
  ('Günde yaklaşık kaç litre sıvı lenf damarlarıyla dolaşıma geri döner?', '2-4', ['0,2-0,4', '10-12', '20-25'], 'Her gün yaklaşık 2-4 litre sıvı kılcallardan sızıp lenf yoluyla dolaşıma döner; bu miktar kan plazmasının önemli bir bölümüdür.'),
  ('Kılcal damar türlerinden gözenekli (fenestralı) kılcallar hangi dokuda yaygındır?', 'Böbrek glomerülleri ve bağırsak villusları', ['Beyin ve omurilik', 'Kas ve kemik', 'Akciğer ve plevra'], 'Gözenekli kılcallar hızlı madde geçişine uygundur; beyinde ise sürekli yapıdaki kılcallar kan-beyin bariyerini oluşturur.'),
  ('Enterik sinir sisteminin iki ana sinir ağı hangileridir?', 'Myenterik ve submukozal pleksus', ['Parasempatik ve sempatik ganglion', 'Beyin sapı ve talamik çekirdek', 'Vagus ve sakral pleksus'], 'Kas katmanları arasındaki myenterik (Auerbach) pleksus hareketi, submukozadaki pleksus ise salgı ve kan akımını yönetir.'),
  ('Onikiparmak bağırsağı submukozasında bulunan ve alkali mukus salgılayan bezlere ne ad verilir?', 'Brunner bezleri', ['Lieberkühn kriptleri', 'Peyer plakları', 'Langerhans adacıkları'], 'Brunner bezleri bikarbonatlı mukus salgılayarak mide asidinin duodenum mukozasına zararını azaltır.'),
  ('İnce bağırsakta kript hücrelerinin salgıladığı sıvı için aşağıdakilerden hangisi doğrudur?', 'Sulu ve elektrolitli bir salgıdır, enzim yerine su ve iyon sağlar', ['Pepsinojen açısından zengin ve asidiktir', 'Safra tuzu içeren ve yağı sindiren salgıdır', 'Amilaz ve lipaz açısından zengindir'], 'Lieberkühn kriptleri yaklaşık 1-2 L/gün bağırsak suyu salgılar; enzimler esasen villus yüzeyindedir.'),
  ('Villus yüzeyi epitel hücrelerinin ortalama yaşam süresi yaklaşık kaç gündür?', '3-5', ['30-45', '1-2 ay', '6 ay'], 'Bağırsak epiteli hızla yenilenir; hücreler kriptten yukarı çıkarak yaklaşık 3-5 günde dökülür.'),
  ('Yüksek lifli bir diyetin kalın bağırsak bakterilerince fermente edilmesi sonucunda oluşan ve kolon hücreleri için enerji kaynağı olan madde grubu hangisidir?', 'Kısa zincirli yağ asitleri', ['Uzun zincirli doymuş yağ asitleri', 'Safra tuzları', 'Peptit hormonları'], 'Bütirat gibi kısa zincirli yağ asitleri kolon epiteli için başlıca enerji kaynağıdır.'),
  ('Antibiyotik kullanımı sonrası bağırsak florasının bozulmasıyla Clostridioides difficile\'ye bağlı ishalin artmasının nedeni nedir?', 'Rekabet eden normal bakterilerin azalması', ['Mide asidinin artması', 'Safra salgısının artması', 'Pankreas enzimlerinin bozulması'], 'Normal flora yok edilince dirençli bakteriler aşırı çoğalır; toksinleri ishale yol açar.'),
  ('Barrett özofagusunda yemek borusunun alt bölümünde hangi değişim olur?', 'Yassı epitel yerine bağırsak benzeri epitelin gelişmesi', ['Kas katmanının incelip kaybolması', 'Mukusun artması ve alt sfinkterin güçlenmesi', 'Epitelin tamamen dökülüp yeniden oluşmaması'], 'Kronik reflü epitelde metaplaziye yol açar; yemek borusu kanseri riskini artırır.'),
  ('Yutmadan sonra yemek borusu boyunca ilerleyen ikincil peristaltik dalga hangi uyaranla başlar?', 'Yemek borusunda kalan besinin duvarı germesi', ['Midenin kasılması', 'Safra salgısı', 'Tükürük amilazı'], 'Birincil dalga yutmayla başlar; kalan besin duvarı gerince ikincil dalga tetiklenir.'),
  ('Şiddetli kusma sonrasında mide asidi kaybı (metabolik alkaloz) hâlinde solunum nasıl bir yanıt verir?', 'Yavaşlar ve yüzeyselleşir', ['Hızlanır ve derinleşir, CO2 atımı artar', 'Kalıcı olarak durur', 'Değişmez'], 'pH yükseldiğinde solunum azalır ve CO2 tutulur; böylece pH düşürülmeye çalışılır.'),
  ('Bir kişi fiziksel egzersize başladığında solunum hızı kandaki CO2\'den önce arttığına göre solunumun artmasının erken nedeni nedir?', 'Kaslardaki hareket reseptörlerinden ve beyin kabuğundan gelen uyarılar', ['Kan pH\'ının önceden düşmesi', 'Alveol yüzey geriliminin aniden artması', 'Böbreklerden gelen hormonlar'], 'Egzersizin başlangıcında eklem ve kas duyu uçları solunum merkezini uyarır; sonra kimyasal uyaranlar devreye girer.'),
  ('Bağırsak emiliminde Na+/K+ ATPaz pompasının görevi aşağıdakilerden hangisidir?', 'Hücre içi sodyumu düşük tutarak glukoz ve amino asit taşınmasını dolaylı sürmesini sağlamak', ['Sodyumu hücre içinde biriktirmek ve ATP üretmek', 'Glukozu doğrudan kana pompalamak', 'Safra tuzlarını geri emmek'], 'Pompa sodyum gradyanını korur; SGLT1 gibi kotaşıyıcılar bu gradyandan yararlanır (ikincil aktif taşıma).'),
  ('Villus hücresinden kana glukoz geçişi hangi taşıma biçimiyle olur?', 'GLUT2 aracılı kolaylaştırılmış difüzyon', ['Sodyum bağımlı aktif taşıma', 'Pinositoz', 'Lipit tabakası içinden enerjisiz basit difüzyon ve çözünme'], 'Glukoz apikal yüzeyden SGLT1 ile alınır, bazolateral yüzeyden GLUT2 ile kana verilir.'),
  ('Kalsiyum emilimi için hem D vitamini hem hangi hormonun varlığı önemlidir?', 'Paratiroit hormonu', ['Tiroksin', 'Kortizol', 'Oksitosin'], 'PTH, böbrekte D vitamininin etkin biçimini artırır; böylece bağırsaktan kalsiyum emilimi yükselir.'),
  ('Sindirim kanalında hangi hormon yağ sindirim ürünlerinin varlığında insülin salgısını da uyararak tokluk bildirir?', 'GIP ve GLP-1 gibi inkretin hormonları', ['Gastrin ve motilin', 'Kortizol ve aldosteron', 'Tiroksin ve kalsitonin'], 'İnkretinler bağırsakta besin varlığında salgılanır ve insülin salgısını artırır.'),
  ('Motilin hormonunun sindirim kanalındaki etkisi nedir?', 'Açlık döneminde bağırsak hareketlerini düzenli aralıklarla başlatmak', ['Mide asidini azaltmak', 'Pankreastan bikarbonat salgılatmak', 'Safra kesesini boşaltmak'], 'Motilin açlık dönemlerinde yaklaşık 90 dakikalık aralıklarla temizleme hareketlerini (MMC) başlatır.'),
  ('Somatostatin hormonunun sindirimdeki genel etkisi aşağıdakilerden hangisidir?', 'Gastrin, sekretin ve CCK gibi sindirim hormonlarının salgısını baskılamak', ['Mide asidi salgısını artırmak', 'Safra yapımını artırmak', 'İnce bağırsak hareketini hızlandırmak'], 'Somatostatin (D hücrelerinden) sindirim salgılarını ve hareketlerini yavaşlatan bir hormondur.'),
  ('Aort duvarının çok elastik olması ve hemen ardından gelen büyük atardamarların daha kaslı olması hangi işleve hizmet eder?', 'Aortta basınç dalgalanmalarını tamponlamak, küçük atardamarlarda akımı ayarlamak', ['Aortta kapakçık yapımını sağlamak, küçük atardamarlarda ısıyı artırmak', 'Aortta gaz alışverişi yapmak, küçük atardamarlarda besin emmek', 'Aortta kan pıhtılaşmasını başlatmak, küçük atardamarlarda yıkım yapmak'], 'Elastik arterler sistolik basınç artışını emerek akımı düzgünleştirir; kaslı arterler damar çapını ayarlayarak dağılımı kontrol eder.'),
  ('Vasa vasorum, büyük damarların hangi gereksinimini karşılar?', 'Kendi duvarlarının beslenmesini', ['Alyuvarların yıkımını', 'Kanın pıhtılaşmasını', 'Lenfin taşınmasını'], 'Büyük damarların kalın duvarı lümenden difüzyonla yeterince beslenemez; vasa vasorum adlı küçük damarlar duvarı besler.'),
  ('Endotel hücrelerinin salgıladığı nitrik oksit (NO) damar üzerinde hangi etkiyi yapar?', 'Damar düz kaslarını gevşetip genişletir', ['Damar düz kaslarını kasıp daraltarak basıncı yükseltir', 'Pıhtılaşmayı başlatır', 'Kan hücrelerini yıkar'], 'NO düz kası gevşeterek damarı genişletir ve tansiyonu düşürür; nitrogliserin bu yolla anjinayı rahatlatır.'),
  ('Statin grubu ilaçlar kan yağlarını nasıl azaltır?', 'Karaciğerde kolesterol sentezini yavaşlatarak', ['Bağırsaktan yağ emilimini tamamen keserek ve safrayı bloke ederek', 'Safra tuzlarının üretimini artırarak', 'Pankreas lipazını artırarak'], 'Statinler HMG-CoA redüktaz enzimini baskılar; karaciğer kolesterol yapımı azalır ve LDL düşer.'),
  ('Yüksek LDL düzeyinin ateroskleroza yol açma mekanizması nedir?', 'Oksitlenmiş LDL\'nin damar duvarında makrofajlarca yutulup köpük hücreleri oluşturması', ['LDL\'nin alyuvarları parçalayıp damarı tıkaması', 'LDL\'nin trombositleri yok edip kanamaya yol açması', 'LDL\'nin damar duvarındaki kasları tamamen eritmesi'], 'Köpük hücreleri yağ çizgisi ve plağı oluşturur; zamanla damar daralır.'),
  ('Geçici iskemik atak (TIA) için doğru ifade hangisidir?', 'Kısa süreli geçici beyin kan akımı azalması; ciddi inme habercisi olabilir', ['Beyin dokusunun kalıcı ölümüyle sonuçlanan kanama', 'Kalbin ritminin tamamen durması', 'Akciğerde pıhtı tıkanması'], 'TIA belirtileri dakikalar içinde düzelir ama gelecekteki inme riskini artırır.'),
  ('Sol kalp yetmezliğinde akciğerde sıvı birikmesinin nedeni nedir?', 'Sol kulakçık ve pulmoner ven basıncının yükselmesi', ['Sağ karıncığın aşırı güçlü kasılması', 'Albüminin akciğere dolması', 'Alveol duvarının incelmesi'], 'Sol karıncık kanı yeterince atamayınca basınç akciğer damarlarına yansır; sıvı alveollere geçer.'),
  ('Anaflaktik şokta kan basıncının hızla düşmesinin nedeni nedir?', 'Damarların yaygın genişleyip kılcal geçirgenliğin artması', ['Kalbin aşırı güçlü kasılması', 'Alyuvar sayısının artması', 'Plazma proteinlerinin yükselmesi'], 'Histamin damarları genişletir ve sıvıyı dokuya kaçırır; basınç düşer ve bilinç bulanır.'),
  ('Aort kapağının açılışında oluşan ve kolda nabız olarak hissedilen dalga hangi hızla ilerler?', 'Kan akış hızından çok daha hızlı', ['Kan akış hızıyla aynı hızda', 'Kan akış hızından çok daha yavaş ilerler', 'Işık hızına yakın hızda'], 'Nabız dalgası yaklaşık 5-10 m/s ilerler; kanın kendisi çok daha yavaş akar.'),
  ('Karotis sinüs masajı (boyunda karotis damarına baskı) yapıldığında kalp hızı neden yavaşlayabilir?', 'Baroreseptörlerin uyarılması ve vagus aktivitesinin artması', ['Kalp kapakçığının kapanması', 'SA düğümün yok olması', 'Kanın pıhtılaşması'], 'Basınç artışı algılanır, vagal uyarı artar; kalp hızı yavaşlar. Bu yöntem bazı ritim bozukluklarında kullanılır.'),
  ('Soğuk bir kış gününde parmak uçlarındaki hemoglobinin oksijen ilgisi sıcaklık düştüğü için nasıl değişir?', 'Artar', ['Azalır ve oksijen parmaklara daha kolay bırakılır, doku besleme zorlaşmaz', 'Değişmez çünkü sıcaklığın hemoglobinle ilişkisi yoktur', 'Tamamen kaybolur ve oksijen bağlanması durur'], 'Sıcaklık düşünce hemoglobinin oksijene ilgisi artar; soğuk dokuda oksijen daha az bırakılır.'),
  ('Akciğer dokusunun elastikiyetinin yaşla azalması (kompliyans artışı) nedeniyle yaşlılarda hangi değer yükselir?', 'Artık hacim', ['Yaşamsal kapasite ve soluk alma yedek hacmi birlikte', 'Soluk hacmi ve alveol yüzey alanı', 'Soluk verme gücü ve diyafram kalınlığı'], 'Elastik geri çekme azaldıkça akciğer tam boşalamaz; artık hacim artar, yaşamsal kapasite düşer.'),
  ('Gebelikte büyüyen rahmin diyaframı yukarı itmesine rağmen gebe kadında solunum yetersizliği gelişmemesini sağlayan uyum aşağıdakilerden hangisidir?', 'Soluk hacmindeki artış', ['Alveol sayısındaki artış ve alyuvar yıkımı hızlanması sonucu yeni solunum yüzeyi', 'Akciğer hacminin yarı yarıya artması ve ölü boşluğun azalması', 'Kalp hızındaki azalma ve soluk verme yedek hacmindeki artış'], 'Progesteron solunum merkezini uyarır; soluk hacmi ve dakika ventilasyonu artar, CO2 düşer.'),
  ('Kafeinin bronşlar üzerindeki hafif genişletici etkisi nedeniyle astım tedavisinde teofilin kullanılması neye dayanır?', 'Bronş düz kaslarının gevşemesine', ['Bronş düz kaslarının güçlü kasılmasına ve mukus salgısının azalmasına', 'Alveol duvarının incelip yüzeyin artmasına', 'Sürfaktan yapımının artmasına'], 'Teofilin ve kafein metilksantin yapılıdır; bronş düz kasını gevşetir ve hava yolunu açar.'),
  ('Alveol duvarında oksijenin kana geçişini engelleyen akciğer fibrozisi hangi tür solunum sorununa yol açar?', 'Kısıtlayıcı (akciğerin sertleşip genişleyememesi)', ['Tıkayıcı (hava yollarının daralması)', 'Merkezi (solunum merkezinin baskılanması)', 'Nöromüsküler (solunum kaslarının felci)'], 'Fibrozda akciğer sertleşir, hacim ve yaşamsal kapasite düşer; bu kısıtlayıcı akciğer hastalığıdır.'),
  ('Plazma elektrolitlerinden potasyum yüksekliği (hiperkalemi) kalbi nasıl etkiler?', 'Ritim bozukluklarına ve kalp durmasına yol açabilir', ['Kalp hızını sürekli düşürür ve kapakçıkları kalınlaştırır', 'Kalp kasını kalıcı olarak güçlendirir', 'Yalnızca kan basıncını yükseltip ritmi etkilemez'], 'Potasyum membran potansiyelini etkiler; yüksekliği kalpte iletim bozukluğu ve fibrilasyon yapar.'),
];
